def forward(groups):
    size_value = float(groups[3])
    size_unit = groups[5]
    free_value = float(groups[8])
    free_unit = groups[10]

    size_scale = {'B': 1, 'KB': 1024, 'MB': 1024 ** 2}
    free_scale = {'B': 1, 'KB': 1024, 'MB': 1024 ** 2}

    size_canonical = int(size_value * size_scale[size_unit])
    free_canonical = int(free_value * free_scale[free_unit])

    spaces_size = len(groups[2])
    spaces_free = len(groups[7])

    return {
        'stored': [size_canonical, free_canonical],
        'layout': [size_unit, free_unit, spaces_size, spaces_free]
    }

def inverse(record):
    size_canonical, free_canonical = record['stored']
    size_unit, free_unit, spaces_size, spaces_free = record['layout']

    size_scale = {'B': 1, 'KB': 1024, 'MB': 1024 ** 2}
    free_scale = {'B': 1, 'KB': 1024, 'MB': 1024 ** 2}

    size_value = size_canonical / size_scale[size_unit]
    free_value = free_canonical / free_scale[free_unit]

    size_spaces = ' ' * spaces_size
    free_spaces = ' ' * spaces_free

    return f"estimated{size_spaces}size{free_spaces}{size_value:.1f} {size_unit}, free{free_spaces}{free_value:.1f} {free_unit}"
